1	package security
2	
3	import (
4		"errors"
5		"log"
6		"time"
7	
8		tea "charm.land/bubbletea/v2"
9	
10		"github.com/anthnel/devdesk/internal/scan"
11		"github.com/anthnel/devdesk/internal/ui/shortcut"
12	)
13	
14	// The Change section of the finding detail (DEVDESK-753): what the built-in fix
15	// would write, computed off Update by the Cmd the detail starts when it opens,
16	// stored by Update, and read from the model by the header, ctrl+o and the Fix
17	// line, which therefore read no disk (Rule 130).
18	
19	// maxChangeRows is how many rows of the diff the section shows; the
20	// confirmation of ctrl+o has all of them.
21	const maxChangeRows = 8
22	
23	// labelChange is the label of the section, and noChangeText what it says when
24	// DevDesk has no change to show (the closed vocabulary of the line).
25	const (
26		labelChange         = "Change: "
27		noChangeText        = "none: DevDesk cannot write this fix"
28		preparingChange     = "preparing the preview..."
29		preparingFooter     = "Preparing the change preview..."
30		footerPreviewFailed = "Could not preview the fix — check logs"
31	)
32	
33	// previewState is what the stored preview knows. The "expired" state is the
34	// stale one: previewStale is already the name of the time comparison.
35	type previewState int
36	
37	const (
38		previewPending  previewState = iota // asked, not answered yet
39		previewReady                        // the change was computed
40		previewDeclined                     // the rule declines this instance (or the path is refused)
41		previewExpired                      // the file changed after the scan
42		previewFailed                       // the computation failed (unreadable, gone)
43	)
44	
45	// ChangePreviewMsg is the answer to the preview Cmd (Rule 109): the shared
46	// computation's message, numbered so a late one is ignored.
47	type ChangePreviewMsg struct {
48		Seq      int
49		Target   string
50		Prepared MisconfigFixPreparedMsg
51	}
