53	// changePreview is the preview of the finding on screen, kept by Update. The
54	// zero value is "no request": Seq starts at 1.
55	type changePreview struct {
56		Seq      int
57		Target   string
58		Finding  scan.Finding
59		State    previewState
60		Prepared MisconfigFixPreparedMsg
61		Failure  string
62	}
63	
64	// scannedAt is when the result on screen was measured, the zero time when it
65	// does not say.
66	func (m Model) scannedAt() time.Time {
67		if m.result == nil {
68			return time.Time{}
69		}
70		return m.result.EndTime
71	}
72	
73	// startChangePreview stores a pending preview of the finding on screen and
74	// returns the Cmd that computes it, or nil when there is nothing to compute: not
75	// a detail, not a catalog rule, not a directory, or a refusal the finding alone
76	// settles. It mutates the model, so it is called from Update only; the finding is
77	// copied into the Cmd (Rule 110).
78	func (m *Model) startChangePreview() tea.Cmd {
79		if m.state != StateDetails || m.selectedFinding == nil {
80			return nil
81		}
82		f := *m.selectedFinding
83		if _, a := misconfigFixAvailability(f, m.targetOnDisk()); !a.Enabled() {
84			return nil
85		}
86		m.previewSeq++
87		seq, target, scannedAt := m.previewSeq, m.targetPath, m.scannedAt()
88		m.changePreview = changePreview{Seq: seq, Target: target, Finding: f, State: previewPending}
89		return func() tea.Msg {
90			return ChangePreviewMsg{Seq: seq, Target: target, Prepared: computeMisconfigFix(target, f, scannedAt)}
91		}
92	}
93	
94	// restartChangePreview asks again, for a file the fix just rewrote, and shows
95	// the section as preparing at once.
96	func (m *Model) restartChangePreview() tea.Cmd {
97		cmd := m.startChangePreview()
98		if cmd != nil {
99			m.detailsViewport.SetContent(m.buildDetailsContent())
100		}
101		return cmd
102	}
103	
104	// handleChangePreview stores the answer when it is the current one: the number,
105	// the target and the finding on screen must all be the request's.
106	func (m Model) handleChangePreview(msg ChangePreviewMsg) (tea.Model, tea.Cmd) {
107		p := m.changePreview
108		if m.state != StateDetails || m.selectedFinding == nil || p.Seq == 0 || msg.Seq != p.Seq ||
109			msg.Target != p.Target || !sameFinding(*m.selectedFinding, p.Finding) {
110			return m, nil
111		}
112		p.Prepared = msg.Prepared
113		var cmd tea.Cmd
114		switch err := msg.Prepared.Err; {
115		case err == nil:
116			p.State = previewReady
117		case isStale(err):
118			p.State = previewExpired
119		case declinedReason(err) != "":
120			p.State = previewDeclined
121		default:
122			log.Printf("ERROR [security/misconfig] preview %s: %v", p.Finding.ID, err)
123			p.State, p.Failure = previewFailed, previewFailure(p.Finding.File, err)
124			cmd = m.footer.Error(footerPreviewFailed)
125		}
126		m.changePreview = p
127		m.detailsViewport.SetContent(m.buildDetailsContent())
128		return m, cmd
129	}
