131	// declinedReason is the reason of a catalog refusal, "" for any other error.
132	func declinedReason(err error) string {
133		var d errDeclined
134		if errors.As(err, &d) {
135			return d.reason
136		}
137		return ""
138	}
139	
140	// isStale says whether err is the refusal of a file written after the scan.
141	func isStale(err error) bool { return declinedReason(err) == reasonPreviewStale }
142	
143	// storedPreview is the stored preview when it is about f.
144	func (m Model) storedPreview(f scan.Finding) (changePreview, bool) {
145		p := m.changePreview
146		if m.state != StateDetails || p.Seq == 0 || p.Target != m.targetPath || !sameFinding(p.Finding, f) {
147			return changePreview{}, false
148		}
149		return p, true
150	}
