152	// previewVerdict is what the stored preview says about ctrl+o, read with no I/O:
153	// a stale or declined preview greys it with its reason. A pending or failed one
154	// leaves it lit, since not knowing is not a no (Rule 130): the press computes the
155	// fix again and reports its own error.
156	func (m Model) previewVerdict(f scan.Finding) shortcut.Availability {
157		p, ok := m.storedPreview(f)
158		if !ok {
159			return shortcut.Availability{}
160		}
161		switch p.State {
162		case previewExpired, previewDeclined:
163			return shortcut.Unavailable(declinedReason(p.Prepared.Err))
164		}
165		return shortcut.Availability{}
166	}
