181	// previewingStatus says whether the footer announces the preview: while the
182	// answer for the finding on screen is awaited.
183	func (m Model) previewingStatus() bool {
184		if m.selectedFinding == nil {
185			return false
186		}
187		p, ok := m.storedPreview(*m.selectedFinding)
188		return ok && p.State == previewPending
189	}
