204	// detailsPreview is the section of a stored preview.
205	func (m Model) detailsPreview(p changePreview, t detailsText) []string {
206		switch p.State {
207		case previewPending:
208			return t.field(labelChange, preparingChange, t.text)
209		case previewExpired:
210			return t.field(labelChange, "stale preview: "+p.Finding.File+" changed after the scan", t.text)
211		case previewFailed:
212			return t.field(labelChange, "preview failed: "+p.Failure, t.text)
213		case previewDeclined:
214			return t.field(labelChange, noChangeText, t.text)
215		}
216		lines := t.field(labelChange, p.Prepared.File.File, t.text)
217		rows, hidden := p.Prepared.Lines, 0
218		if len(rows) > maxChangeRows {
219			rows, hidden = rows[:maxChangeRows], len(rows)-maxChangeRows
220		}
221		for _, row := range rows {
222			lines = append(lines, t.text.Render(oneLine(row, t.width)))
223		}
224		if more := moreLines(hidden); more != "" {
225			lines = append(lines, t.text.Render(more))
226		}
227		return append(lines, t.field("Git: ", gitAdvice(p.Prepared.File), t.text)...)
228	}
