230	// versionDelta is "<pkg> <version> -> <fixed>" for a vulnerability with a fixed
231	// version, the one scan.PickFixed chooses (the whole FixedIn when it cannot
232	// choose, as the command DevDesk offers does).
233	func versionDelta(f scan.Finding) (string, bool) {
234		if f.PkgName == "" || f.Version == "" || f.FixedIn == "" {
235			return "", false
236		}
237		fixed := scan.PickFixed(f.Version, f.FixedIn)
238		if fixed == "" {
239			fixed = f.FixedIn
240		}
241		return f.PkgName + " " + f.Version + " -> " + fixed, true
242	}
